-- Phase 6 migration: optional count breakdown per observation.
alter table observations
  add column if not exists male_count int,
  add column if not exists female_count int,
  add column if not exists unidentified_count int;

do $$ begin
  alter table observations
    add constraint observations_male_count_non_negative_check
    check (male_count is null or male_count >= 0) not valid;
exception when duplicate_object then null; end $$;

do $$ begin
  alter table observations
    add constraint observations_female_count_non_negative_check
    check (female_count is null or female_count >= 0) not valid;
exception when duplicate_object then null; end $$;

do $$ begin
  alter table observations
    add constraint observations_unidentified_count_non_negative_check
    check (unidentified_count is null or unidentified_count >= 0) not valid;
exception when duplicate_object then null; end $$;

do $$ begin
  alter table observations
    add constraint observations_count_breakdown_sum_check
    check (
      (
        male_count is null
        and female_count is null
        and unidentified_count is null
      )
      or (
        coalesce(male_count, 0) + coalesce(female_count, 0) + coalesce(unidentified_count, 0) = count
      )
    ) not valid;
exception when duplicate_object then null; end $$;

alter table observations validate constraint observations_male_count_non_negative_check;
alter table observations validate constraint observations_female_count_non_negative_check;
alter table observations validate constraint observations_unidentified_count_non_negative_check;
alter table observations validate constraint observations_count_breakdown_sum_check;

-- Harden storage insert policy: only allow upload to own folder (auth.uid prefix)
drop policy if exists "Authenticated users can upload photos" on storage.objects;

create policy "Authenticated users can upload photos"
  on storage.objects for insert
  with check (
    bucket_id = 'photos'
    and auth.role() = 'authenticated'
    and auth.uid()::text = (storage.foldername(name))[1]
  );

-- Theme 5: Sync & Integrity corrections (non-destructive, zero-downtime)

-- SI-18: FK ON DELETE CASCADE (GDPR art. 17)
ALTER TABLE observations DROP CONSTRAINT IF EXISTS observations_user_id_fkey;
ALTER TABLE observations
  ADD CONSTRAINT observations_user_id_fkey
  FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

-- SI-19: RLS UPDATE WITH CHECK (prevent user_id transfer)
DROP POLICY IF EXISTS "Users can update their own observations" ON observations;
CREATE POLICY "Users can update their own observations"
  ON observations FOR UPDATE
  USING (auth.uid() = user_id)
  WITH CHECK (auth.uid() = user_id);

-- SI-22: CHECK length constraints
DO $$ BEGIN
  ALTER TABLE observations
    ADD CONSTRAINT observations_location_max_length_check
    CHECK (location IS NULL OR char_length(location) <= 500) NOT VALID;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
ALTER TABLE observations VALIDATE CONSTRAINT observations_location_max_length_check;

DO $$ BEGIN
  ALTER TABLE observations
    ADD CONSTRAINT observations_comment_max_length_check
    CHECK (comment IS NULL OR char_length(comment) <= 5000) NOT VALID;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
ALTER TABLE observations VALIDATE CONSTRAINT observations_comment_max_length_check;

DO $$ BEGIN
  ALTER TABLE observations
    ADD CONSTRAINT observations_latin_name_max_length_check
    CHECK (latin_name IS NULL OR char_length(latin_name) <= 200) NOT VALID;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
ALTER TABLE observations VALIDATE CONSTRAINT observations_latin_name_max_length_check;

-- SI-23: taxonomic_group NOT NULL DEFAULT 'Autre'
UPDATE observations SET taxonomic_group = 'Autre' WHERE taxonomic_group IS NULL;
ALTER TABLE observations ALTER COLUMN taxonomic_group SET DEFAULT 'Autre';
DO $$ BEGIN
  ALTER TABLE observations
    ADD CONSTRAINT observations_taxonomic_group_not_null_check
    CHECK (taxonomic_group IS NOT NULL) NOT VALID;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
ALTER TABLE observations VALIDATE CONSTRAINT observations_taxonomic_group_not_null_check;

-- SI-24: Protect created_at from client modification
CREATE OR REPLACE FUNCTION public.set_observations_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at = timezone('utc'::text, now());
  NEW.created_at = OLD.created_at;
  RETURN NEW;
END;
$$;

-- Frontend compatible déployé et contrôle utilisateur effectué.
-- Aucun déplacement ni suppression des fichiers ou références historiques.
UPDATE storage.buckets SET public = false WHERE id = 'photos';

